/*
 * SialTV — site stylesheet
 * Visual styles moved out of per-page <style> blocks.
 * Utilities first; each template profile is scoped to body[data-css="pN"].
 * :root tokens are applied on the matching body so CSS variables inherit.
 */

/* === Utilities (replaced repeated inline styles) === */
.u-mt-10 { margin: 10px 0 0; }
.u-mt-12 { margin: 12px 0 0; }
.u-mt-8 { margin: 8px 0 0; }
.u-mb-10 { margin: 0 0 10px; }
.u-m-0 { margin: 0; }
.u-sr-only { position: absolute; opacity: 0; width: 1px; height: 1px; }

/* --- profile p0: 131 page(s), e.g. ilt20/players/liam-livingstone/index.html --- */
body[data-css="p0"].league-npl {--accent:#d21034;--league:#d21034}
body[data-css="p0"].league-ilt20 {--accent:#1d4ed8;--league:#1d4ed8}
body[data-css="p0"].league-apl {--accent:#0e1038;--league:#0e1038}
body[data-css="p0"].league-sa20 {--accent:#009444;--league:#009444}
body[data-css="p0"].league-bbl {--accent:#0e7490;--league:#0e7490}
