body[data-css="p0"], body[data-css="p0"] * {box-sizing:border-box}
body[data-css="p0"] a {color:var(--blue);text-decoration:none}
body[data-css="p0"] a:hover {text-decoration:underline}
body[data-css="p0"] a:focus-visible {outline:3px solid var(--focus);outline-offset:2px}
body[data-css="p0"] .wrap {max-width:1280px;margin:0 auto;padding:0 16px}
body[data-css="p0"] h1, body[data-css="p0"] h2, body[data-css="p0"] h3 {font-family:"Archivo",ui-sans-serif,sans-serif;font-weight:800;line-height:1.08;letter-spacing:-.01em}
body[data-css="p0"] h1 {font-size:40px}
body[data-css="p0"] h2 {font-size:24px;margin:0 0 12px}
body[data-css="p0"] h3 {font-size:19px}
body[data-css="p0"] p {margin:0 0 12px}
body[data-css="p0"] .num {font-variant-numeric:tabular-nums}
body[data-css="p0"] .brand:hover {text-decoration:none}
body[data-css="p0"] nav.leagues {display:flex;flex-wrap:wrap;gap:0;margin-left:auto}
body[data-css="p0"] .live-dot {display:inline-block;width:8px;height:8px;background:var(--red);border-radius:50%;margin-right:6px;vertical-align:middle;animation:pulse 1.8s infinite}
