body[data-css="p0"] .subnav b {background:var(--red);color:#fff;font-weight:800;font-size:12px;letter-spacing:.06em;text-transform:uppercase;padding:2px 8px;border-radius:4px}
body[data-css="p0"] .subnav .t-time {font-weight:700;white-space:nowrap}
body[data-css="p0"] .hero-home {background:var(--hero-navy);color:#fff;padding:34px 0 28px;border-bottom:3px solid var(--red)}
body[data-css="p0"] .hero-home h1 {color:#fff;font-size:46px}
