body[data-css="p0"] .hero-home .updated {color:#8fa9c4;font-size:14px}
@keyframes pulse-white {0%{box-shadow:0 0 0 0 rgba(255,255,255,.55)}70%{box-shadow:0 0 0 7px rgba(255,255,255,0)}100%{box-shadow:0 0 0 0 rgba(255,255,255,0)}}
body[data-css="p0"] .crumbs {font-size:14px;color:var(--muted);padding:0;margin:0 0 8px}
