body[data-css="p0"] .today strong {font-size:22px;font-weight:800;display:block;margin:6px 0}
body[data-css="p0"] .today p {margin:0 0 6px;color:var(--ink-2)}
body[data-css="p0"] .today p:last-child {margin:0}
body[data-css="p0"] .today a {font-weight:700}
body[data-css="p0"] .today .t-time {font-weight:700}
body[data-css="p0"] .tile .meta {color:var(--muted);font-size:15px;display:block;margin-bottom:8px}
body[data-css="p0"] .tile-stat {display:block;font-size:13px;font-weight:700;color:var(--ink-2);padding-top:10px;margin-top:2px;border-top:1px dashed var(--rule-2)}
body[data-css="p0"] td {font-variant-numeric:tabular-nums}
body[data-css="p0"] td:nth-child(2) {font-weight:700}
body[data-css="p0"] .table-scroll {overflow-x:auto}
body[data-css="p0"] .teams {display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}
body[data-css="p0"] .team {background:var(--card);border:1px solid var(--rule);border-top:3px solid var(--league,#0860c4);border-radius:10px;padding:12px 14px}
body[data-css="p0"] .team b {font-size:18px}
body[data-css="p0"] .team p {margin:4px 0 0;color:var(--muted);font-size:15px}
body[data-css="p0"] .faq h3 {margin:16px 0 4px}
body[data-css="p0"] .faq p {margin:0 0 10px}
body[data-css="p0"] .note {font-size:14px;color:var(--muted)}
body[data-css="p0"] .foot-cols {display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:24px;padding-bottom:8px}
@media (max-width:900px) {

}
@media (max-width:640px) {
body[data-css="p0"] nav.leagues a {font-size:14px;padding:6px 8px}
body[data-css="p0"] .top-date {display:none}
body[data-css="p0"] .hero p, body[data-css="p0"] .hero-home p {font-size:16px}
