}
body[data-css="p0"] {--navy-2:#06509e;--red:#ff4538;--red-tint:#fdecea;--card:#ffffff;--ink:#0f1014;--ink-2:#2c3a46;--muted:#4b5166;--league:#0860c4;--bg:#ffffff;--blue:#c92a1e;--red-text:#c92a1e;--navy:#0f1014;--hero-navy:#0f1014;--rule:#e5e5e5;--rule-2:#e0e0e0;--focus:#c92a1e}
